export function AccentColour({
  accent = "{{accent}}",
  checked = {{checked}},
  rangeValue = {{rangeValue}},
  label = "{{label}}",
}) {
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", width: 280 }}>
      <label style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14 }}>
        <input type="checkbox" style={{ accentColor: accent, width: 18, height: 18 }} checked={checked} readOnly /> {label}
      </label>
      <input type="range" min={0} max={100} value={rangeValue} readOnly style={{ accentColor: accent, width: "100%", display: "block", marginBottom: 14 }} aria-label="Volume" />
      <button type="button" style={{ background: accent, border: "none", padding: "10px 16px", borderRadius: 8, color: "#241430", fontWeight: 700, fontSize: 13 }}>
        Primary action
      </button>
      <p style={{ marginTop: 4, fontSize: 12, color: "#241430cc" }}>accent-color: {accent} &mdash; the browser tints native controls without extra markup</p>
    </div>
  );
}
